dir:


















































&DefaultButton;




function dir$qlhccong(p){
  this.constructor(p);
}
dir$qlhccong.prototype = new DirEvent();
dir$qlhccong.prototype.afterInit = function(){
  var p = this._dir;
}
dir$qlhccong.prototype.afterInit = function(renderType){
  var p = this._dir;
dir$qlhccongDisabledMasterField(p);
dir$tlhccongDisabledStatusByAction(p);
}
dir$qlhccong.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_hccong':
      dir$qlhccongLoadDulieu(p);
      break;
    default:
      break;
  }
}
function dir$qlhccongDisabledMasterField(p){
var maPl = p.valForm('ma_hccong');
	if(maPl) {
		p.setDisabled('ma_hccong', true);
	} else {
		p.setDisabled('ma_hccong', false);
	}
}
function dir$qlhccongLoadDulieu(p){
var maHcCong = p.valForm('ma_hccong');

	if (p.options.action == 'NEW') {
		p.request('requestHCCONG', '', [['ma_hccong', 'C', maHcCong]])
	}
}
function dir$tlhccongDisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=4],[value=6],[value=7],[value=9],[value=5],[value=0]").remove();
}






.modal-dialog-lg{min-width:720px!important;}
.control-label.tt {color: #499b98; text-decoration: underline}
.control-label.ma_hccong, .control-label.stt {color: #499b98;}






		IF EXISTS (SELECT 1 FROM dmhccong WHERE ma_hccong = @ma_hccong) BEGIN
			exec [st_QueryHCCONG] @ma_hccong

		END
		ELSE BEGIN
			SELECT 0 [!stt], '' [!thoi_gian], '' [!tg_dukienbd], '' [!tg_dukienkt], N'Chưa khai báo hành chính công vui lòng thử lại' as warning
		END





select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table
drop table #@@table






update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]






if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, '@@firstFieldKey' as field
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit






update #data set unit_id = @@unit
@@insert
